import type { LogEntry, WorkflowRunState } from '../../types';

// ─── Develop renderer types ─────────────────────────────────────────────────

export interface DevelopPhaseInfo {
  id: string;
  label: string;
  icon: string;
  status: 'completed' | 'active' | 'pending';
}

export interface DevelopAgentInfo {
  agentId: string;
  profile: string;
  taskId?: string;
  active: boolean;
  log: LogEntry[];
}

export interface DevelopRendererState {
  phases: DevelopPhaseInfo[];
  agents: DevelopAgentInfo[];
  currentPhase: string;
}

// ─── Helper ─────────────────────────────────────────────────────────────────

export function buildDevelopState(runState: WorkflowRunState): DevelopRendererState {
  const phases: DevelopPhaseInfo[] = [];
  const sidebarPhases = runState.summary.sidebar.phases;
  if (sidebarPhases) {
    for (const phase of sidebarPhases) {
      let status: 'completed' | 'active' | 'pending';
      if (runState.completedPhases.includes(phase.id)) {
        status = 'completed';
      } else if (phase.id === runState.currentPhase) {
        status = 'active';
      } else {
        status = 'pending';
      }
      phases.push({
        id: phase.id,
        label: phase.label,
        icon: phase.icon,
        status,
      });
    }
  }

  const agents: DevelopAgentInfo[] = [];
  for (const [agentId, agent] of runState.agents) {
    agents.push({
      agentId: agent.agentId,
      profile: agent.profile,
      taskId: agent.taskId,
      active: agent.active,
      log: agent.log,
    });
  }
  agents.sort((a, b) => a.agentId.localeCompare(b.agentId));

  return {
    phases,
    agents,
    currentPhase: runState.currentPhase,
  };
}

/**
 * Tests for develop renderer types and the buildDevelopState helper.
 */

import { describe, it, expect } from 'vitest';

import type {
  WorkflowRunState,
  WorkflowSummary,
  AgentWindowState,
  PhaseDescriptor,
  LogEntry,
} from '../../../types';
import { buildDevelopState } from '../types';
import type {
  DevelopPhaseInfo,
  DevelopAgentInfo,
  DevelopRendererState,
} from '../types';

// ─── Helpers ────────────────────────────────────────────────────────────────

function createPhase(id: string, label?: string, icon?: string): PhaseDescriptor {
  return { id, label: label ?? id, icon: icon ?? '🔵' };
}

function createAgentWindow(agentId: string, overrides: Partial<AgentWindowState> = {}): AgentWindowState {
  return {
    agentId,
    profile: 'default',
    active: false,
    log: [],
    ...overrides,
  };
}

function createSummary(overrides: Partial<WorkflowSummary> = {}): WorkflowSummary {
  return {
    id: 'test-run',
    workflowName: 'Test Workflow',
    status: 'running',
    sidebar: {
      title: 'Test',
      indicator: '…',
      ...('sidebar' in overrides ? {} : { phases: [] }),
    },
    startedAt: new Date().toISOString(),
    ...overrides,
    // Ensure sidebar always has phases unless explicitly overridden
    sidebar: {
      title: 'Test',
      indicator: '…',
      ...(overrides.sidebar ?? { phases: [] }),
    },
  };
}

function createRunState(overrides: Partial<WorkflowRunState> = {}): WorkflowRunState {
  return {
    summary: createSummary(),
    agents: new Map(),
    currentPhase: '',
    completedPhases: [],
    ...overrides,
  };
}

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('buildDevelopState', () => {
  describe('phases', () => {
    it('should return empty phases array when sidebar has no phases', () => {
      const summary = createSummary({ sidebar: { title: 'No phases', indicator: '…' } });
      const state = createRunState({ summary });
      const result = buildDevelopState(state);
      expect(result.phases).toEqual([]);
    });

    it('should return empty phases array when sidebar.phases is undefined', () => {
      const summary = createSummary({ sidebar: { title: 'No phases', indicator: '…', phases: undefined } });
      const state = createRunState({ summary });
      const result = buildDevelopState(state);
      expect(result.phases).toEqual([]);
    });

    it('should mark a phase as completed when its id is in completedPhases', () => {
      const phases: PhaseDescriptor[] = [
        createPhase('phase-1', 'Phase 1', '📋'),
        createPhase('phase-2', 'Phase 2', '⚙️'),
      ];
      const summary = createSummary({ sidebar: { title: 'Test', indicator: '…', phases } });
      const state = createRunState({
        summary,
        currentPhase: 'phase-2',
        completedPhases: ['phase-1'],
      });
      const result = buildDevelopState(state);
      expect(result.phases).toHaveLength(2);
      expect(result.phases[0].status).toBe('completed');
